import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getTranslations } from "next-intl/server";
import { getContent } from "@/lib/content";
import { getAllSlugs } from "@/lib/taxonomy";
import { DreamHero } from "@/components/dream/DreamHero";
import { DreamSection } from "@/components/dream/DreamSection";
import { DreamVariations } from "@/components/dream/DreamVariations";
import { DreamFAQ } from "@/components/dream/DreamFAQ";
import { RelatedDreams } from "@/components/dream/RelatedDreams";
import { MarkdownBody } from "@/components/dream/MarkdownBody";
import type { Locale } from "@/i18n/routing";

type Props = {
  params: Promise<{ locale: string; slug: string }>;
};

export async function generateStaticParams() {
  const slugs = await getAllSlugs();
  return slugs.flatMap(({ slug, koreanSlug }) => [
    { locale: "en", slug },
    { locale: "ko", slug: koreanSlug },
  ]);
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { locale, slug } = await params;
  const content = await getContent(slug, locale as Locale);
  if (!content) return {};

  const { seo } = content;

  return {
    title: locale === "ko" ? content.ko.title : content.en.title,
    description:
      locale === "ko"
        ? content.ko.metaDescription
        : content.en.metaDescription,
    alternates: {
      canonical: seo.hreflang[locale as Locale],
      languages: {
        ko: seo.hreflang.ko,
        en: seo.hreflang.en,
      },
    },
    openGraph: {
      title: seo.ogTitle[locale as Locale],
      description: seo.ogDescription[locale as Locale],
      images: seo.ogImage ? [seo.ogImage] : [],
    },
  };
}

function detectSectionType(heading: string): "auspicious" | "inauspicious" | "neutral" {
  if (heading.includes("길몽") || /auspicious/i.test(heading)) return "auspicious";
  if (heading.includes("흉몽") || /inauspicious/i.test(heading)) return "inauspicious";
  return "neutral";
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function getBody(item: any): string {
  return item.content ?? item.body ?? "";
}

export default async function DreamPage({ params }: Props) {
  const { locale, slug } = await params;
  const content = await getContent(slug, locale as Locale);

  if (!content) notFound();

  const t = await getTranslations({ locale, namespace: "dream" });
  const c = locale === "ko" ? content.ko : content.en;

  const jsonLd = [
    content.seo.structuredData.faqSchema,
    content.seo.structuredData.articleSchema,
  ].filter(Boolean);

  return (
    <>
      {jsonLd.map((schema, i) => (
        <script
          key={i}
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }}
        />
      ))}

      <article className="mx-auto max-w-3xl px-4 py-8 sm:px-6">
        {/* Hero card */}
        <div className="mb-4 rounded-2xl bg-white p-6 shadow-sm">
          <DreamHero
            title={c.h1}
            intro={c.intro}
            heroImage={content.images?.hero}
            locale={locale as Locale}
          />
        </div>

        {/* Interpretation sections */}
        {c.sections.map((section, i) => (
          <DreamSection
            key={i}
            heading={section.heading}
            body={getBody(section)}
            type={(section as any).type ?? detectSectionType(section.heading)}
            image={
              (section as any).imageRef
                ? content.images?.sections?.[(section as any).imageRef]
                : undefined
            }
          />
        ))}

        {/* Variations */}
        <div className="mt-4 rounded-2xl bg-white p-6 shadow-sm">
          <DreamVariations
            heading={t("variations")}
            variations={c.variations.map((v) => ({
              keyword: (v as any).keyword ?? "",
              heading: v.heading,
              body: getBody(v),
            }))}
          />
        </div>

        {/* Cultural context */}
        <div className="mt-4 rounded-2xl bg-white p-6 shadow-sm">
          <h2 className="mb-3 text-xl font-semibold text-gray-900">{t("culturalContext")}</h2>
          <MarkdownBody className="text-gray-700">{c.culturalContext}</MarkdownBody>
        </div>

        {/* Western psychological context */}
        {c.westernContext && (
          <div className="mt-4 rounded-2xl bg-indigo-600 p-6 shadow-sm">
            <h2 className="mb-3 text-xl font-semibold text-white">
              {locale === "ko" ? "서양 심리학적 해석" : "Western Psychological Perspectives"}
            </h2>
            <MarkdownBody className="text-indigo-100">{c.westernContext}</MarkdownBody>
          </div>
        )}

        {/* FAQ */}
        <div className="mt-4 rounded-2xl bg-white p-6 shadow-sm">
          <DreamFAQ heading={t("faq")} faqs={c.faqs} />
        </div>

        {/* Conclusion */}
        {c.conclusion && (
          <div className="mt-4 rounded-2xl bg-white p-6 shadow-sm">
            <MarkdownBody className="text-gray-600 italic">{c.conclusion}</MarkdownBody>
          </div>
        )}

        {/* Related dreams */}
        <div className="mt-4 rounded-2xl bg-white p-6 shadow-sm">
          <RelatedDreams
            heading={t("relatedDreams")}
            slugs={content.seo.relatedSlugs ?? []}
            locale={locale as Locale}
          />
        </div>
      </article>
    </>
  );
}

import Image from "next/image";
import { MarkdownBody } from "./MarkdownBody";

const TYPE_STYLES = {
  auspicious: "border-t-4 border-emerald-400",
  inauspicious: "border-t-4 border-red-400",
  neutral: "border-t-4 border-gray-300",
} as const;

type Props = {
  heading: string;
  body: string;
  type: string;
  image?: string;
};

export function DreamSection({ heading, body, type, image }: Props) {
  const accent =
    TYPE_STYLES[type as keyof typeof TYPE_STYLES] ?? TYPE_STYLES.neutral;

  return (
    <section className={`mt-4 rounded-2xl bg-white p-6 shadow-sm ${accent}`}>
      <h2 className="mb-3 text-xl font-semibold text-gray-900">{heading}</h2>
      {image && (
        <div className="relative mb-4 w-full overflow-hidden rounded-lg aspect-[3/2]">
          <Image
